w.tanda("hapus"); w.kam("table", zoom=1.2); time.sleep(1.0); hapus("Gimbal kamera"); w.kam("main", zoom=1.2); w.label("Belum pernah dipinjam: terhapus", 4.5); time.sleep(5.5)
